  function onClick(sel, handler){
    const el = document.querySelector(sel);
    if(el) el.addEventListener('click', handler);
  }
  function onFill(sel, handler){
    const el=document.querySelector(sel);
    if(!el) return;
    // emulate contract fill: we trigger on input event then blur? evaluator uses fill then expects immediate effects. We'll trigger on input and change.
    el.addEventListener('input', (e)=>{ handler(e.target.value); });
  }
  function onFile(sel, handler){
    const el=document.querySelector(sel);
    if(!el) return;
    el.addEventListener('change', async (e)=>{
      const file = e.target.files && e.target.files[0];
      if(!file) return;
      const text = await file.text();
      const rows = parseCSV(text);
      handler(file, rows);
      // keep selected file
    });
  }

  function parseCSV(text){
    const lines = text.replace(/\r/g,'').trim().split(/\n+/);
    if(lines.length<2) return [];
    const header = splitCSVLine(lines[0]);
    const colIndex = {};
    header.forEach((h,i)=>colIndex[h.trim()] = i);
    const out=[];
    for(let i=1;i<lines.length;i++){
      const line=lines[i];
      if(!line.trim()) continue;
      const parts=splitCSVLine(line);
      const row={};
      for(const [name, idx] of Object.entries(colIndex)){
        row[name] = (parts[idx] ?? '').trim();
      }
      // contract schema types are all string; keep string.
      out.push(row);
    }
    return out;
  }

  function splitCSVLine(line){
    // Simple CSV splitter handling quoted fields.
    const res=[];
    let cur='';
    let inQ=false;
    for(let i=0;i<line.length;i++){
      const ch=line[i];
      if(ch==='"'){
        if(inQ && line[i+1]==='"'){ cur+='"'; i++; }
        else inQ = !inQ;
      } else if(ch===',' && !inQ){
        res.push(cur);
        cur='';
      } else {
        cur+=ch;
      }
    }
    res.push(cur);
    return res;
  }

  function syncRouteFromLocation(){
    const page = parsePageFromLocation();
    state.current_page = page;
    updatePageVisibility();
  }

  window.addEventListener('hashchange', ()=>{
    syncRouteFromLocation();
    applyStateProbeAndRender();
    persist();
  });

  // Apply initial route
  syncRouteFromLocation();

  // Setup static actions (depends on DOM)
  registerStaticActions();

  // Render + attach dynamic selection
  applyStateProbeAndRender();
  registerDynamicPatientSelection();

  // Re-bind dynamic selection after each render cycle triggered by render.
  // We hook into render by overriding applyStateProbeAndRender? easiest: call registerDynamicPatientSelection at end via requestAnimationFrame.
  const _orig = applyStateProbeAndRender;
  applyStateProbeAndRender = function(){
    _orig();
    requestAnimationFrame(()=>registerDynamicPatientSelection());
  };

})();
